// Birdle: Squaredle-style word search on bird-themed boards.
// Boards come from boards.js, generated by tools/gen.py.

// Share of the board's points needed for each star: red numbers, white numbers, hints.
// The first star sits at the points the board's birds are worth, so finding all
// the birds first earns it; the others are at 60% and 80% (or evenly spaced
// above the first star if the birds are worth more than that).
function starThresholds() {
  const birds = board.birds.reduce((t, b) => t + points(b.word), 0) / totalPoints;
  return [birds, Math.max(0.6, birds + (1 - birds) / 3), Math.max(0.8, birds + (2 * (1 - birds)) / 3)];
}
let STARS = [];
const MIN_LEN = 4;
const $ = (id) => document.getElementById(id);

const store = {
  get(key) { try { return JSON.parse(localStorage.getItem(key)); } catch { return null; } },
  set(key, value) { try { localStorage.setItem(key, JSON.stringify(value)); } catch {} },
};

let board, size, letters, required, bonusSet, birdWords, totalPoints, state;
let path = [];        // tile indices of the word being built
let typed = false;    // whether the current path came from the keyboard
let rotation = 0;

// Longer words score more, and the region's birds score double.
const BIRD_MULTIPLIER = 2;
const points = (w) => (w.length - 3) * (birdWords.has(w) ? BIRD_MULTIPLIER : 1);

// How many letters the letter hint reveals at the start and end of a word, by length.
function revealed(len) {
  if (len <= 5) return [1, 0];
  if (len === 6) return [2, 0];
  if (len === 7) return [2, 1];
  if (len <= 10) return [2, 2];
  if (len <= 14) return [3, 2];
  return [3, 3];
}
function hinted(w) {
  const [head, tail] = revealed(w.length);
  return w.slice(0, head) + '_'.repeat(w.length - head - tail) + (tail ? w.slice(-tail) : '');
}

// ----- screens ---------------------------------------------------------------

const boardLabel = (b) => `${b.level} · ${b.size}×${b.size}`;

function showRegions() {
  $('regions').hidden = false; $('game').hidden = true; $('back').hidden = true;
  const list = $('region-list');
  list.innerHTML = '';
  let region;
  for (const b of BOARDS) {
    if (b.region !== region) {
      region = b.region;
      const h = document.createElement('li');
      h.className = 'region-head';
      h.innerHTML = `<span class="flag">${b.flag}</span> ${b.name}`;
      list.append(h);
    }
    const saved = store.get('birdle:' + b.id);
    const s = saved && saved.grid === b.grid.join('') ? saved : null;
    const found = s ? s.found.length : 0;
    const birds = s ? b.birds.filter((x) => s.found.includes(x.word)).length : 0;
    const status = !s ? `${b.birds.length} birds to find`
      : found === b.words.length ? 'Complete ✓'
      : `${birds} of ${b.birds.length} birds · ${found} of ${b.words.length} words`;
    const li = document.createElement('li');
    li.innerHTML = `<button><span class="name">${boardLabel(b)}</span><span class="state">${status}</span></button>`;
    li.querySelector('button').onclick = () => openBoard(b);
    list.append(li);
  }
}

function openBoard(b) {
  board = b;
  size = b.grid.length;
  letters = b.grid.join('');
  required = new Map(b.words.map((w) => [w.w, w]));
  bonusSet = new Set(b.bonus);
  birdWords = new Set(b.birds.map((x) => x.word));
  totalPoints = b.words.reduce((t, w) => t + points(w.w), 0);
  STARS = starThresholds();
  state = store.get('birdle:' + b.id);
  // A regenerated board gets a fresh start; old found words wouldn't be on it.
  if (!state || state.grid !== letters) state = freshState();
  path = []; rotation = 0;
  $('regions').hidden = true; $('game').hidden = false; $('back').hidden = false;
  $('region-name').textContent = `${b.flag} ${b.name} · ${b.level}`;
  $('progress').querySelector('.stars').innerHTML =
    STARS.map((s) => `<span class="star" style="left:${s * 100}%">★</span>`).join('');
  buildBoard();
  render();
  window.scrollTo(0, 0);
}

const save = () => store.set('birdle:' + board.id, state);
const freshState = () => ({ grid: letters, found: [], bonus: [], hintLetters: false, hintSort: false });

// ----- board -----------------------------------------------------------------

function buildBoard() {
  const el = $('board');
  el.style.gridTemplateColumns = `repeat(${size}, 1fr)`;
  el.style.transform = '';
  // Keep letters big on small boards and readable on 7x7 ones.
  const wrap = $('board-wrap');
  wrap.style.setProperty('--letter-size', `min(${(40 / size).toFixed(2)}vw, ${(12 / size).toFixed(2)}rem)`);
  wrap.style.setProperty('--num-size', `min(${(7 / size).toFixed(2)}vw + 0.5rem, ${(6.5 / size).toFixed(2)}rem)`);
  el.innerHTML = '';
  [...letters].forEach((ch, i) => {
    const t = document.createElement('div');
    t.className = 'tile' + (ch === '.' ? ' blank' : '');
    t.dataset.i = i;
    t.innerHTML = `<span class="letter">${ch === '.' ? '' : ch}</span><span class="n start"></span><span class="n use"></span>`;
    el.append(t);
  });
}

const tiles = () => [...$('board').children];
const adjacent = (a, b) => a !== b &&
  Math.abs(Math.floor(a / size) - Math.floor(b / size)) <= 1 && Math.abs((a % size) - (b % size)) <= 1;

// ----- swiping ---------------------------------------------------------------

// Only count a tile when the pointer is near its centre, so diagonal swipes
// don't clip the neighbouring tiles.
function tileAt(x, y) {
  const t = document.elementFromPoint(x, y)?.closest('.tile');
  if (!t || t.classList.contains('blank')) return null;
  const r = t.getBoundingClientRect();
  const dx = x - (r.left + r.width / 2), dy = y - (r.top + r.height / 2);
  return Math.hypot(dx, dy) <= r.width * 0.42 ? +t.dataset.i : null;
}

function extend(i) {
  if (i === null) return;
  if (path.length >= 2 && path[path.length - 2] === i) path.pop();          // backtrack
  else if (!path.length || (adjacent(path[path.length - 1], i) && !path.includes(i))) path.push(i);
  else return;
  renderPath();
}

let dragging = false;
$('board-wrap').addEventListener('pointerdown', (e) => {
  const i = tileAt(e.clientX, e.clientY);
  if (i === null) return;
  e.preventDefault();
  dragging = true; typed = false; path = [];
  $('board-wrap').setPointerCapture(e.pointerId);
  extend(i);
});
$('board-wrap').addEventListener('pointermove', (e) => { if (dragging) extend(tileAt(e.clientX, e.clientY)); });
$('board-wrap').addEventListener('pointerup', (e) => {
  if (!dragging) return;
  dragging = false;
  // Like Squaredle, letting go well above the board cancels the word.
  if (e.clientY < $('board-wrap').getBoundingClientRect().top - 40) return clearPath();
  submit();
});
$('board-wrap').addEventListener('pointercancel', () => { dragging = false; clearPath(); });

// ----- typing ----------------------------------------------------------------

let typedWord = '', typedAlt = 0;

// All ways to spell `word` on the board.
function pathsFor(word) {
  const out = [];
  const walk = (p) => {
    if (p.length === word.length) return out.push(p);
    const last = p[p.length - 1];
    for (let j = 0; j < letters.length; j++) {
      if (letters[j] === word[p.length] && !p.includes(j) && (last === undefined || adjacent(last, j))) walk([...p, j]);
    }
  };
  walk([]);
  return out;
}

function retype() {
  typed = true;
  const options = pathsFor(typedWord);
  path = options.length ? options[typedAlt % options.length] : [];
  renderPath();
}

document.addEventListener('keydown', (e) => {
  if ($('game').hidden || e.metaKey || e.ctrlKey || e.altKey || $('rules').open) return;
  if (e.key === 'Enter') submit();
  else if (e.key === 'Escape') clearPath();
  else if (e.key === 'Backspace') { typedWord = typedWord.slice(0, -1); typedAlt = 0; retype(); }
  else if (e.key === ' ') { typedAlt++; retype(); }      // cycle between same-letter squares
  else if (/^[a-z]$/i.test(e.key)) { typedWord += e.key.toUpperCase(); typedAlt = 0; retype(); }
  else return;
  e.preventDefault();
});

// ----- scoring ---------------------------------------------------------------

function wordOnBoard() {
  return typed ? typedWord : path.map((i) => letters[i]).join('');
}

function submit() {
  const w = wordOnBoard();
  if (typed && w.length && !path.length) { flash(w, 'Not on the board'); return clearPath(); }
  if (w.length === 0) return clearPath();
  if (path.length === 1 && !typed) return clearPath();   // a tap, not a word
  if (w.length < MIN_LEN) flash(w, 'Too short');
  else if (state.found.includes(w) || state.bonus.includes(w)) say(`${w}: already found`, 'neutral');
  else if (required.has(w)) {
    const before = starsEarned();
    state.found.push(w);
    save();
    const bird = board.birds.find((b) => b.word === w);
    const earned = starsEarned();
    if (state.found.length === board.words.length) toast('🎉 Board complete! Every word found.');
    else {
      const star = earned > before
        ? ['★ Red numbers unlocked', '★ White numbers unlocked', '★ Hints unlocked'][earned - 1] : '';
      const found = bird ? `🐦 ${bird.bird}! +${points(w)}` : `${w} +${points(w)}`;
      toast(star ? `${found} · ${star}` : found);
    }
  } else if (bonusSet.has(w)) {
    state.bonus.push(w);
    save();
    toast(`${w}: bonus word`);
  } else flash(w, 'Not in word list');
  clearPath();
  render();
}

function starsEarned() {
  const got = state.found.reduce((t, w) => t + points(w), 0) / totalPoints;
  return STARS.filter((s) => got >= s).length;
}

// ----- rendering -------------------------------------------------------------

function clearPath() { path = []; typedWord = ''; typedAlt = 0; typed = false; renderPath(); }

function renderPath() {
  tiles().forEach((t, i) => t.classList.toggle('sel', path.includes(i)));
  const cur = $('current');
  const word = typed ? typedWord : path.map((i) => letters[i]).join('');
  const msg = !word && message;
  cur.className = msg ? `msg ${msg.kind}` : (typed && word && !path.length ? 'bad' : '');
  cur.textContent = msg ? msg.text : word;
  const wrap = $('board-wrap').getBoundingClientRect();
  const pts = path.map((i) => {
    const r = tiles()[i].getBoundingClientRect();
    return `${r.left + r.width / 2 - wrap.left},${r.top + r.height / 2 - wrap.top}`;
  });
  $('trail').innerHTML = pts.length > 1 ? `<polyline points="${pts.join(' ')}"/>` : '';
}

function render() {
  const stars = starsEarned();
  const got = state.found.reduce((t, w) => t + points(w), 0);
  $('progress').querySelector('.fill').style.width = `${(100 * got) / totalPoints}%`;
  $('progress').querySelectorAll('.star').forEach((s, i) => s.classList.toggle('on', i < stars));

  // Tile numbers count only words still to find; a tile fades when none are left.
  const left = board.words.filter((w) => !state.found.includes(w.w));
  tiles().forEach((t, i) => {
    if (letters[i] === '.') return;
    const starts = left.filter((w) => w.s.includes(i)).length;
    const uses = left.filter((w) => w.u.includes(i)).length;
    const fmt = (n) => (n >= 10 ? '+' : n || '');
    t.querySelector('.start').textContent = stars >= 1 ? fmt(starts) : '';
    t.querySelector('.use').textContent = stars >= 2 ? fmt(uses) : '';
    t.classList.toggle('done', uses === 0);
    t.style.transform = `rotate(${-rotation}deg)`;
  });

  renderBirds();
  $('hints').hidden = stars < 3;
  $('hint-letters').checked = state.hintLetters;
  $('hint-sort').checked = state.hintSort;
  renderWords(stars >= 3);
}

function renderBirds() {
  const found = board.birds.filter((b) => state.found.includes(b.word)).length;
  const showLetters = starsEarned() >= 3 && state.hintLetters;
  $('birds-panel').innerHTML = `<h3>🐦 Birds of ${board.name}: ${found} of ${board.birds.length}</h3>` +
    board.birds.map((b) => state.found.includes(b.word)
      ? `<div class="bird-row"><span class="name">${b.word} · ${b.bird}</span><div class="note">${b.note}</div></div>`
      : `<div class="bird-row"><span class="slots">${showLetters ? hinted(b.word) : '_'.repeat(b.word.length)}</span> <span class="note">${b.word.length} letters</span></div>`
    ).join('');
}

function renderWords(hintsOn) {
  const showLetters = hintsOn && state.hintLetters;
  const sortAll = hintsOn && state.hintSort;
  const byLen = {};
  for (const w of board.words) (byLen[w.w.length] ||= []).push(w.w);
  let html = `<h3>Words: ${state.found.length} of ${board.words.length}</h3>`;
  for (const len of Object.keys(byLen).sort((a, b) => a - b)) {
    const all = byLen[len];
    const found = all.filter((w) => state.found.includes(w));
    // Missing words appear as blanks; with the sort hint they sit in alphabetical order among the found ones.
    const items = sortAll ? all.slice().sort()
      : [...state.found.filter((w) => w.length == len), ...all.filter((w) => !found.includes(w)).sort()];
    html += `<div class="group-title">${len} letters · ${found.length} of ${all.length}</div><div class="words">` +
      items.map((w) => {
        const cls = birdWords.has(w) ? ' bird' : '';
        if (found.includes(w)) return `<span class="word${cls}">${w}</span>`;
        if (!sortAll && !showLetters) return '';
        const shown = showLetters ? hinted(w) : '_'.repeat(w.length);
        return `<span class="word missing">${shown}</span>`;
      }).join('') + '</div>';
  }
  $('word-list').innerHTML = html;
  $('bonus-list').innerHTML = state.bonus.length
    ? `<h3>Bonus words: ${state.bonus.length}</h3><div class="words">${state.bonus.map((w) => `<span class="word">${w}</span>`).join('')}</div>`
    : '';
}

// ----- messages --------------------------------------------------------------

// Messages show on the line above the board, where the word being built goes.
let message = null, messageTimer;
// kind: 'good' (green), 'bad' (red, for words that don't count) or 'neutral'.
function say(text, kind) {
  message = { text, kind };
  clearTimeout(messageTimer);
  messageTimer = setTimeout(() => { message = null; renderPath(); }, 2200);
  renderPath();
}
const toast = (text) => say(text, 'good');
const flash = (word, why) => say(`${word}: ${why.toLowerCase()}`, 'bad');

// ----- controls --------------------------------------------------------------

$('rotate').onclick = () => {
  rotation = (rotation + 90) % 360;
  $('board').style.transform = `rotate(${rotation}deg)`;
  render();
};
$('hint-letters').onchange = (e) => { state.hintLetters = e.target.checked; save(); render(); };
$('hint-sort').onchange = (e) => { state.hintSort = e.target.checked; save(); render(); };
// Two taps to start over, so a stray tap can't wipe a board.
let resetArmed;
$('reset').onclick = () => {
  if (!resetArmed) {
    $('reset').textContent = 'Tap again to clear all found words';
    resetArmed = setTimeout(() => { resetArmed = null; $('reset').textContent = 'Start this board over'; }, 3000);
    return;
  }
  clearTimeout(resetArmed); resetArmed = null;
  $('reset').textContent = 'Start this board over';
  state = freshState();
  save(); render();
};
$('back').onclick = showRegions;
// How to play: a few short screens with Back / Next / Let's play.
const rules = $('rules');
const steps = [...rules.querySelectorAll('.step')];
let step = 0;
function showStep(n) {
  step = n;
  steps.forEach((el, i) => { el.hidden = i !== n; });
  rules.querySelector('.back').disabled = n === 0;
  rules.querySelector('.next').textContent = n === steps.length - 1 ? "Let's play" : 'Next';
  rules.querySelector('.dots').innerHTML = steps.map((_, i) => `<i class="${i === n ? 'on' : ''}"></i>`).join('');
}
function openRules() {
  showStep(0);
  rules.showModal();
  rules.scrollTop = 0;
  rules.querySelector('.next').focus();
}
rules.querySelector('.back').onclick = () => showStep(step - 1);
rules.querySelector('.next').onclick = () => (step < steps.length - 1 ? showStep(step + 1) : rules.close());
rules.querySelector('.close').onclick = () => rules.close();
$('help').onclick = openRules;
window.addEventListener('resize', renderPath);

showRegions();
if (!store.get('birdle:seen-rules')) { store.set('birdle:seen-rules', true); openRules(); }
